import { CancelToken } from "axios";
import AuthHttpClient from "../auth-http-client";
import getEnvVariable from "@/service/env-variable-provider";
import { IRndCellRequestParameters } from "@/models/Rnd/filters/RndCellRequestParameters";
import { IRndCellListDto } from "@/models/Rnd/dtos/RndCellListDto";
import { IRndCyclingStorageDto } from "@/models/Rnd/Experiments/dtos/RndCyclingStorageDto";

const CYCLER_APP_ENDPOINT = "/cycler_app";
const CYCLING_STORATE_ENDPOINT = "/cycling_storage";
const CELLS_ENDPOINT = "/cells";

class RndCyclerTraceabilityApi extends AuthHttpClient {
  constructor() {
    super({
      baseURL: getEnvVariable("VUE_APP_CYCLER_TRACEABILITY_API_BASE_URL"),
      apiRegistrationId: getEnvVariable(
        "VUE_APP_CYCLER_TRACEABILITY_API_APP_REGISTRATION_ID",
      ),
    });
  }

  async fetchCells(
    params: IRndCellRequestParameters,
    cancelToken: CancelToken,
  ): Promise<IRndCellListDto> {
    return this.instance.get<IRndCellListDto, IRndCellListDto>(
      `${CYCLER_APP_ENDPOINT}${CELLS_ENDPOINT}`,
      {
        params,
        cancelToken,
      },
    );
  }

  async fetchCyclingStorage(cell_id: string): Promise<IRndCyclingStorageDto> {
    return this.instance.get<IRndCyclingStorageDto, IRndCyclingStorageDto>(
      `${CYCLING_STORATE_ENDPOINT}/${cell_id}`,
    );
  }
}

export default RndCyclerTraceabilityApi;

